// prettier-ignore
export const GUIDE_HTML: string = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<meta name=\"referrer\" content=\"no-referrer\">\n<title>Manager guide</title>\n<link rel=\"stylesheet\" href=\"/app.css\">\n</head>\n<body class=\"guide-page\">\n<header class=\"guide-top\"><strong>NanoClaw Manager</strong><span class=\"muted\">Guide</span><a class=\"back\" href=\"/\">&larr; Back to the panel</a></header>\n<div class=\"guide-wrap\">\n<nav class=\"guide-toc\" aria-label=\"Contents\">\n<a class=\"toc-2\" href=\"#what-you-get\">What you get</a>\n<a class=\"toc-2\" href=\"#how-it-fits-together\">How it fits together</a>\n<a class=\"toc-2\" href=\"#installing\">Installing</a>\n<a class=\"toc-3\" href=\"#requirements\">Requirements</a>\n<a class=\"toc-3\" href=\"#applying-the-skills\">Applying the skills</a>\n<a class=\"toc-3\" href=\"#after-installing-the-upgrade-check\">After installing: the upgrade check</a>\n<a class=\"toc-2\" href=\"#first-run\">First run</a>\n<a class=\"toc-3\" href=\"#create-the-administrator\">Create the administrator</a>\n<a class=\"toc-2\" href=\"#reaching-the-panel\">Reaching the panel</a>\n<a class=\"toc-3\" href=\"#https-and-network-access\">HTTPS and network access</a>\n<a class=\"toc-2\" href=\"#using-the-dashboard\">Using the dashboard</a>\n<a class=\"toc-3\" href=\"#overview\">Overview</a>\n<a class=\"toc-3\" href=\"#agents\">Agents</a>\n<a class=\"toc-3\" href=\"#model\">Model</a>\n<a class=\"toc-3\" href=\"#backups\">Backups</a>\n<a class=\"toc-2\" href=\"#models\">Models</a>\n<a class=\"toc-3\" href=\"#connecting-an-endpoint\">Connecting an endpoint</a>\n<a class=\"toc-3\" href=\"#the-small-model\">The small model</a>\n<a class=\"toc-3\" href=\"#api-keys\">API keys</a>\n<a class=\"toc-3\" href=\"#ollama\">Ollama</a>\n<a class=\"toc-3\" href=\"#chatgpt\">ChatGPT</a>\n<a class=\"toc-3\" href=\"#claude\">Claude</a>\n<a class=\"toc-3\" href=\"#removing-a-credential\">Removing a credential</a>\n<a class=\"toc-3\" href=\"#how-a-model-change-works\">How a model change works</a>\n<a class=\"toc-3\" href=\"#endpoint-checks-and-errors\">Endpoint checks and errors</a>\n<a class=\"toc-2\" href=\"#backups-1\">Backups</a>\n<a class=\"toc-3\" href=\"#what-a-backup-contains\">What a backup contains</a>\n<a class=\"toc-3\" href=\"#the-backup-key\">The backup key</a>\n<a class=\"toc-3\" href=\"#consistency-levels\">Consistency levels</a>\n<a class=\"toc-3\" href=\"#retention-and-pruning\">Retention and pruning</a>\n<a class=\"toc-3\" href=\"#restoring-a-backup\">Restoring a backup</a>\n<a class=\"toc-3\" href=\"#rehearsal-restore\">Rehearsal restore</a>\n<a class=\"toc-3\" href=\"#moving-to-another-machine\">Moving to another machine</a>\n<a class=\"toc-2\" href=\"#terminal-only-tasks\">Terminal-only tasks</a>\n<a class=\"toc-3\" href=\"#forgotten-password\">Forgotten password</a>\n<a class=\"toc-3\" href=\"#channels-and-agents\">Channels and agents</a>\n<a class=\"toc-3\" href=\"#updating-nanoclaw\">Updating NanoClaw</a>\n<a class=\"toc-3\" href=\"#rebuilding-agent-images\">Rebuilding agent images</a>\n<a class=\"toc-3\" href=\"#removing-the-skills\">Removing the skills</a>\n<a class=\"toc-2\" href=\"#security-model\">Security model</a>\n<a class=\"toc-2\" href=\"#troubleshooting\">Troubleshooting</a>\n<a class=\"toc-2\" href=\"#reference\">Reference</a>\n<a class=\"toc-3\" href=\"#settings\">Settings</a>\n<a class=\"toc-3\" href=\"#terminal-commands\">Terminal commands</a>\n<a class=\"toc-3\" href=\"#files-and-folders\">Files and folders</a>\n<a class=\"toc-3\" href=\"#http-api\">HTTP API</a>\n<a class=\"toc-2\" href=\"#known-limits\">Known limits</a>\n</nav>\n<main class=\"guide\">\n<h1 id=\"manager-guide\">Manager guide<a class=\"anchor\" href=\"#manager-guide\" aria-label=\"Link to this section\">#</a></h1>\n<p>How to install, run and look after a NanoClaw install with the <strong>manager</strong> skills: the web panel (<code>add-manager-panel</code>) and encrypted backups (<code>add-manager-backup</code>).</p>\n<p>This guide is also served by the panel itself at <code>/guide</code>, and the panel links to the sections below wherever something can only be done from a terminal.</p>\n<blockquote><p><strong>Unofficial.</strong> These skills are not part of NanoClaw and are not affiliated with its authors. They attach to upstream NanoClaw through its own extension points and change one line of its source (<code>src/modules/index.ts</code>).</p></blockquote>\n<h2 id=\"what-you-get\">What you get<a class=\"anchor\" href=\"#what-you-get\" aria-label=\"Link to this section\">#</a></h2>\n<div class=\"table-wrap\"><table><tbody><tr><td><strong>Web panel</strong></td><td>Overview, agents (restart), one OpenAI-compatible model endpoint for every agent, backups. Password login, English interface.</td></tr><tr><td><strong>Backups</strong></td><td>Encrypted single-file backups of the whole install, verification, restore with rollback, a rehearsal mode for testing a backup on another machine.</td></tr><tr><td><strong>Terminal tools</strong></td><td><code>scripts/manager-backup.ts</code> and <code>scripts/manager-panel.ts</code>, for everything the panel deliberately does not do.</td></tr></tbody></table></div>\n<p>What the panel does <strong>not</strong> do, on purpose: restore a backup, change passwords without a terminal, store API keys, install channels, update NanoClaw. Those are in <a href=\"#terminal-only-tasks\">Terminal-only tasks</a>.</p>\n<h2 id=\"how-it-fits-together\">How it fits together<a class=\"anchor\" href=\"#how-it-fits-together\" aria-label=\"Link to this section\">#</a></h2>\n<pre><code> browser ──HTTP(S)──▶ panel (inside the NanoClaw host process)\n                         │  reads/writes .env and each group's config\n                         │  restarts agent containers\n                         └─ backup library ──▶ encrypted files in the backups folder\n\n terminal ─▶ scripts/manager-backup.ts   create / verify / restore / commit / rollback / prune\n          └▶ scripts/manager-panel.ts    setup-code / reset-password / unlock / status</code></pre>\n<ul><li>The panel is a <strong>module of the NanoClaw host</strong>: it starts and stops with it. It has the same privileges as the NanoClaw user, so protect access to it like a shell on the machine.</li><li>Models are not run by NanoClaw. Agents call an <strong>OpenAI-compatible HTTP endpoint</strong> you provide (a local server such as llama.cpp or vLLM, or a hosted provider) through upstream's OpenCode provider (<code>add-opencode</code>).</li><li>Credentials for model providers live in the <strong>credential gateway</strong> (OneCLI by default), never in <code>.env</code> and never in a backup.</li></ul>\n<h2 id=\"installing\">Installing<a class=\"anchor\" href=\"#installing\" aria-label=\"Link to this section\">#</a></h2>\n<h3 id=\"requirements\">Requirements<a class=\"anchor\" href=\"#requirements\" aria-label=\"Link to this section\">#</a></h3>\n<ul><li>A working NanoClaw install, version 2.4 or later, with Docker. See upstream's README.</li><li>The credential gateway skill (<code>add-onecli</code>) and the OpenCode provider (<code>add-opencode</code>) installed with upstream's own skills. The panel only writes the settings those read.</li><li>Node 22 or later and pnpm, as NanoClaw itself needs.</li></ul>\n<p>What was actually tested: Debian 13 in an LXC container, Docker 29, Node 22.23, pnpm 10, Bun 1.4.0, NanoClaw <code>main</code> at the time of writing, OneCLI 1.41.0, applying the skills with upstream's own skill engine. Anything else is expected to work but was not tried.</p>\n<h3 id=\"applying-the-skills\">Applying the skills<a class=\"anchor\" href=\"#applying-the-skills\" aria-label=\"Link to this section\">#</a></h3>\n<p>Get this repository, then copy the two skill folders into the install:</p>\n<pre><code class=\"language-bash\">cp -r skills-for-nanoclaw/.claude/skills/add-manager-backup  ~/nanoclaw/.claude/skills/\ncp -r skills-for-nanoclaw/.claude/skills/add-manager-panel   ~/nanoclaw/.claude/skills/</code></pre>\n<p>Apply them in this order. In Claude Code, from the install folder:</p>\n<pre><code>/add-manager-backup\n/add-manager-panel</code></pre>\n<p>Each skill checks its prerequisites, copies its files, builds, typechecks and runs its tests. The panel skill also appends one line, <code>import './manager-panel/index.js';</code>, to <code>src/modules/index.ts</code>. Both are safe to repeat.</p>\n<p>To apply them without an agent (this is how they are tested), the repository has a script that does it with upstream's own engine on a clean checkout:</p>\n<pre><code class=\"language-bash\">node scripts/compose.mjs --upstream https://github.com/nanocoai/nanoclaw.git</code></pre>\n<h3 id=\"after-installing-the-upgrade-check\">After installing: the upgrade check<a class=\"anchor\" href=\"#after-installing-the-upgrade-check\" aria-label=\"Link to this section\">#</a></h3>\n<p>NanoClaw refuses to start when its files changed outside its own setup or update flow. Installing a skill counts as such a change, and you will see an <em>&quot;upgrade tripwire&quot;</em> message. Once the build and tests of the skills passed, record the new state and start again:</p>\n<pre><code class=\"language-bash\">pnpm exec tsx scripts/upgrade-state.ts set</code></pre>\n<p>Then rebuild if you changed code (<code>pnpm run build</code>) and restart the NanoClaw service.</p>\n<h2 id=\"first-run\">First run<a class=\"anchor\" href=\"#first-run\" aria-label=\"Link to this section\">#</a></h2>\n<p>After restarting, the host log says where the panel listens, for example:</p>\n<pre><code>Manager panel listening  bind=127.0.0.1 port=3200 https=false\nManager panel has no administrator yet. Run: pnpm exec tsx scripts/manager-panel.ts setup-code</code></pre>\n<h3 id=\"create-the-administrator\">Create the administrator<a class=\"anchor\" href=\"#create-the-administrator\" aria-label=\"Link to this section\">#</a></h3>\n<pre><code class=\"language-bash\">pnpm exec tsx scripts/manager-panel.ts setup-code</code></pre>\n<p>It prints the panel address and a one-time code such as <code>ABCD-EFGH-JKMN-PQRS</code>. Open the address, enter the code and choose a password of at least 12 characters. The code works once and expires after 30 minutes; run the command again for a new one. There is one administrator account.</p>\n<h2 id=\"reaching-the-panel\">Reaching the panel<a class=\"anchor\" href=\"#reaching-the-panel\" aria-label=\"Link to this section\">#</a></h2>\n<p>By default the panel listens on <code>127.0.0.1:3200</code>: only the machine itself can open it. Options:</p>\n<ul><li><strong>From the same machine:</strong> open <code>http://127.0.0.1:3200</code>.</li><li><strong>From another computer, through SSH</strong> (nothing to configure): <code>ssh -L 3200:127.0.0.1:3200 user@the-machine</code>, then open <code>http://127.0.0.1:3200</code> locally.</li><li><strong>From other devices on the local network:</strong> see <a href=\"#https-and-network-access\">HTTPS and network access</a>.</li></ul>\n<h3 id=\"https-and-network-access\">HTTPS and network access<a class=\"anchor\" href=\"#https-and-network-access\" aria-label=\"Link to this section\">#</a></h3>\n<p>Settings go in the install's <code>.env</code> file; restart NanoClaw after changing them.</p>\n<p>To allow other devices on your network:</p>\n<pre><code>PANEL_BIND=0.0.0.0</code></pre>\n<p>Even then, connections from public internet addresses are refused, and the request's <code>Host</code> name must be local: an IP address, <code>localhost</code>, a single-word name, or a name ending in <code>.local</code>, <code>.lan</code>, <code>.internal</code> or <code>.home.arpa</code>. For any other name, list it:</p>\n<pre><code>PANEL_ALLOWED_HOSTS=panel.example.org,nas.mydomain.net</code></pre>\n<p><strong>Without HTTPS</strong> the panel works but shows a warning on every page (except on localhost): your password and backup keys cross the network unencrypted. That can be acceptable on a trusted home network. Choose one of these to encrypt the connection:</p>\n<ol><li><strong>Your own certificate</strong>, served by the panel:\n<pre><code>PANEL_TLS_CERT=/path/to/cert.pem\nPANEL_TLS_KEY=/path/to/key.pem</code></pre>\n<p>The files are read when NanoClaw starts. The panel does not create or renew certificates.</p></li><li><strong>A reverse proxy that terminates TLS.</strong> Keep the panel on localhost, point the proxy at it, and tell the panel the exact address the browser uses:\n<pre><code>PANEL_BIND=127.0.0.1\nPANEL_PUBLIC_ORIGIN=https://panel.example.org\nPANEL_ALLOWED_HOSTS=panel.example.org</code></pre>\n<p>An example for nginx (not tested here; adapt it):</p>\n<pre><code>server {\n  listen 443 ssl;\n  server_name panel.example.org;\n  # ssl_certificate / ssl_certificate_key ...\n  client_max_body_size 0;\n  location / {\n    proxy_pass http://127.0.0.1:3200;\n    proxy_set_header Host $host;\n    proxy_buffering off;\n    proxy_read_timeout 300s;\n  }\n}</code></pre>\n<p>The long read timeout matters: creating a backup can wait for running agents (up to <code>PANEL_BACKUP_WAIT_SECONDS</code>, 120 by default), and downloads can be large.</p></li></ol>\n<p>With HTTPS the session cookie becomes <code>__Host-manager_panel</code> with the <code>Secure</code> flag, and the <code>Strict-Transport-Security</code> header is sent.</p>\n<p>If a page loads but every action fails with <em>origin_mismatch</em>, the address in the browser differs from the one the panel expects: set <code>PANEL_PUBLIC_ORIGIN</code> exactly to what the address bar shows (scheme, name and port, no trailing slash).</p>\n<h2 id=\"using-the-dashboard\">Using the dashboard<a class=\"anchor\" href=\"#using-the-dashboard\" aria-label=\"Link to this section\">#</a></h2>\n<p>Sign in with the administrator password. Sessions end after 30 minutes without activity or 8 hours in total. Wrong passwords: five are free, then every further failure doubles a lock (one minute, two, four, up to an hour). Sensitive actions (applying a model, creating, downloading or deleting a backup) ask for the password again if you have not typed it in the last five minutes.</p>\n<h3 id=\"overview\">Overview<a class=\"anchor\" href=\"#overview\" aria-label=\"Link to this section\">#</a></h3>\n<p>Release, how many agents exist and how many are working, sessions, uptime, the credential gateway, installed channels and providers, and the number and date of backups.</p>\n<h3 id=\"agents\">Agents<a class=\"anchor\" href=\"#agents\" aria-label=\"Link to this section\">#</a></h3>\n<p>One row per agent: provider, model and whether it is working. <strong>Restart</strong> stops the agent's containers; the next message starts a fresh one with the current settings. Adding, wiring and removing agents is not done here: see <a href=\"#channels-and-agents\">Channels and agents</a>.</p>\n<h3 id=\"model\">Model<a class=\"anchor\" href=\"#model\" aria-label=\"Link to this section\">#</a></h3>\n<p>The page shows the endpoint and model all agents use. See <a href=\"#models\">Models</a> for how to use it.</p>\n<h3 id=\"backups\">Backups<a class=\"anchor\" href=\"#backups\" aria-label=\"Link to this section\">#</a></h3>\n<p>The list of backups with date, size, release and consistency, and the actions Verify, Download and Delete. See <a href=\"#backups\">Backups</a>. Restoring is not offered here: see <a href=\"#restoring-a-backup\">Restoring a backup</a>.</p>\n<h2 id=\"models\">Models<a class=\"anchor\" href=\"#models\" aria-label=\"Link to this section\">#</a></h2>\n<p>The <strong>Model</strong> page sets one provider for every agent. Three kinds are offered:</p>\n<div class=\"table-wrap\"><table><thead><tr><th>Provider</th><th>What it is</th><th>Credential</th></tr></thead><tbody><tr><td><strong>OpenAI-compatible endpoint</strong></td><td>Any server that speaks the OpenAI API: a local model server, <a href=\"#ollama\">Ollama</a>, or a hosted service. Agents use OpenCode.</td><td>None for most local servers; a key for hosted ones (<a href=\"#api-keys\">API keys</a>)</td></tr><tr><td><strong><a href=\"#chatgpt\">ChatGPT</a></strong></td><td>OpenAI models through your ChatGPT subscription or an OpenAI API key. Agents use OpenCode.</td><td>Subscription login or API key</td></tr><tr><td><strong><a href=\"#claude\">Claude</a></strong></td><td>Anthropic models through the Claude provider NanoClaw ships with.</td><td>API key or Claude subscription token</td></tr></tbody></table></div>\n<p>Choosing a provider and pressing <strong>Apply</strong> changes every agent at once, with the same rollback as described in <a href=\"#how-a-model-change-works\">How a model change works</a>. The page shows which provider is in use.</p>\n<h3 id=\"connecting-an-endpoint\">Connecting an endpoint<a class=\"anchor\" href=\"#connecting-an-endpoint\" aria-label=\"Link to this section\">#</a></h3>\n<p>An endpoint is the base URL of an OpenAI-compatible API, ending in <code>/v1</code>, for example <code>http://model-server:8000/v1</code> or <code>https://api.example-provider.com/v1</code>.</p>\n<ol><li>Open <strong>Model</strong>. Enter the endpoint and the model name exactly as the server lists it.</li><li>Press <strong>Check endpoint</strong>. The panel asks the server for its model list, confirms your model is in it, and sends a one-token test request. The list becomes the suggestions of the model field.</li><li>If the check passed, <strong>Apply to all agents</strong> becomes available. It asks for your password.</li></ol>\n<p>Rules the panel enforces on the address:</p>\n<ul><li>Loopback, private-network (home or office LAN, VPN) and unique-local addresses may use plain HTTP.</li><li>A public address must use HTTPS.</li><li>Link-local addresses (including cloud metadata services), multicast and reserved ranges are refused.</li><li>No credentials, query string or fragment in the URL.</li></ul>\n<p>From inside the agent containers the machine running NanoClaw is reachable at the Docker bridge address (shown by <code>docker network inspect bridge</code>, usually the first one in the 172.17 range) or at <code>host.docker.internal</code>; <code>localhost</code> inside a container is the container itself. A model server on the same machine as NanoClaw therefore needs an address such as <code>http://&lt;bridge-address&gt;:8000/v1</code> and must listen on that interface, not only on <code>127.0.0.1</code>.</p>\n<h3 id=\"the-small-model\">The small model<a class=\"anchor\" href=\"#the-small-model\" aria-label=\"Link to this section\">#</a></h3>\n<p>OpenCode, the provider that talks to the endpoint, can use a second, lighter model for minor background work. The field <strong>Small model (optional)</strong> sets it. Leave it empty to use the main model for everything, which is the right choice when you run a single model. The panel does not check that the small model exists on the endpoint; a wrong name shows up when OpenCode first tries to use it.</p>\n<h3 id=\"api-keys\">API keys<a class=\"anchor\" href=\"#api-keys\" aria-label=\"Link to this section\">#</a></h3>\n<p>Model providers' keys and tokens are kept in the <strong>credential gateway</strong> (OneCLI), never in <code>.env</code> and never in a backup. There are two ways to put one there:</p>\n<ul><li><strong>In the panel.</strong> On the ChatGPT and Claude forms, paste the key and press <strong>Save</strong>. The password is asked again first. The value goes from your browser to the panel, to a helper process, to the gateway, and is never shown or returned again. Saving again replaces the stored value and keeps the agents' access to it.</li><li><strong>From a terminal</strong>, with upstream's tool, which also covers keys for a hosted OpenAI-compatible service:\n<pre><code class=\"language-bash\">pnpm exec tsx setup/index.ts --step provider-auth opencode</code></pre>\n<p>Choose the local or self-hosted option, enter the endpoint and, when asked, the key.</p></li></ul>\n<blockquote><p><strong>Over plain HTTP a key crosses your network in clear text</strong> when you paste it into the panel. The panel warns about this on every page except localhost. Use localhost, an SSH tunnel or <a href=\"#https-and-network-access\">HTTPS</a> when you enter secrets.</p></blockquote>\n<p>Entering keys in the panel needs the OpenCode and OneCLI skills installed (<code>add-opencode</code>, <code>add-onecli</code>) because the helper that stores them is built on those. Without them the panel says so and simply does not offer ChatGPT or Claude credentials.</p>\n<p>A <em>401</em> result from <strong>Check endpoint</strong> (<em>the endpoint wants an API key</em>) means the key is missing or the endpoint is not the one the key was stored for.</p>\n<h3 id=\"ollama\">Ollama<a class=\"anchor\" href=\"#ollama\" aria-label=\"Link to this section\">#</a></h3>\n<p><a href=\"https://ollama.com\" target=\"_blank\" rel=\"noopener noreferrer\">Ollama</a> runs models on your own machine and speaks the OpenAI API at <code>http://&lt;address&gt;:11434/v1</code>. The panel uses it as an OpenAI-compatible endpoint; no key is needed.</p>\n<ol><li>Install Ollama and pull a model that supports tool calls, for example <code>ollama pull &lt;model&gt;</code>. Agents use tools heavily, and models without reliable tool use do poorly.</li><li>Make Ollama reachable <strong>from the agent containers</strong>. By default it listens on <code>127.0.0.1</code> only, which a container cannot reach. Set <code>OLLAMA_HOST=&lt;bridge address&gt;:11434</code> in Ollama's service environment and restart it (the Docker bridge address is what <strong>Use Ollama</strong> shows; <code>0.0.0.0</code> also works but opens the port to your network). Remember to set the same <code>OLLAMA_HOST</code> when you run <code>ollama pull</code>.</li><li>On the <strong>Model</strong> page choose <em>OpenAI-compatible endpoint</em> and press <strong>Use Ollama</strong>. It fills in the Docker bridge address of this machine with port 11434 and checks it; the models you pulled appear as suggestions in the <strong>Model</strong> field.</li><li>Pick a model, <strong>Check endpoint</strong>, then <strong>Apply to all agents</strong>.</li></ol>\n<p><strong>Speed.</strong> An agent's first request carries about 2,000 tokens of instructions. On a CPU-only machine a 3-billion-parameter model reads them at roughly 40 tokens a second, so even a small model needs a minute or more before it starts to answer, and more again to write the reply. A GPU, or a hosted endpoint, is the practical choice for day-to-day use. The first <strong>Check endpoint</strong> can also be slow, because the model is loaded into memory by that first request; for a model on this machine the panel waits up to two minutes for it.</p>\n<p><strong>Model size.</strong> In a test on a CPU-only machine, <code>qwen2.5:3b</code> took about ten minutes to answer a greeting, and the answer was not in the format agents must use (a <code>&lt;message to=&quot;...&quot;&gt;</code> block), so nothing was delivered: it talked about creating a directory it had no reason to touch. The pipeline (panel, endpoint, agent, model) worked; the model was too small and too slow for an agent. Expect to need a much larger model and a GPU for useful results.</p>\n<p><strong>Context window.</strong> Ollama's default window is 4,096 tokens (<code>OLLAMA_CONTEXT_LENGTH</code> in its service environment raises it). Agents with long conversations or many tools need more; if answers stop following the instructions, raise it. Ollama does not report the window to the panel, so the panel leaves the context limits unset for it.</p>\n<p>NanoClaw's own skill for Ollama (<code>add-ollama-provider</code>) takes a different route: it points the Claude provider at Ollama's Anthropic-style API and edits each agent's container settings. The panel does not use it. The two should not be combined.</p>\n<h3 id=\"chatgpt\">ChatGPT<a class=\"anchor\" href=\"#chatgpt\" aria-label=\"Link to this section\">#</a></h3>\n<p>Agents reach OpenAI through OpenCode, with the credential injected by the gateway. Two ways to authenticate:</p>\n<ul><li><strong>Subscription login.</strong> Press <strong>Sign in with ChatGPT</strong> (the password is asked again). The panel starts OpenCode's device pairing in a short-lived container and shows a page and a code. Open the page, sign in to ChatGPT there and enter the code. The panel waits up to 15 minutes and stores the login in the gateway, which refreshes it by itself. <strong>Cancel</strong> stops the attempt.</li><li><strong>API key.</strong> Paste an OpenAI API key and press <strong>Save</strong>.</li></ul>\n<p>Then enter the <strong>model name exactly as OpenAI names it</strong>, optionally a small model, and press <strong>Apply</strong>. The panel cannot check the name: the credential lives in the gateway and cannot be read back to ask OpenAI. A wrong name shows up the first time an agent tries to use it.</p>\n<p>What Apply writes: <code>OPENCODE_PROVIDER=openai</code>, <code>OPENCODE_BASE_URL=native</code>, <code>OPENCODE_MODEL</code> and <code>OPENCODE_SMALL_MODEL</code> as <code>openai/&lt;name&gt;</code>, and for a subscription login <code>OPENCODE_AUTH_MODE=chatgpt</code> (removed for an API key). Any context limits from an earlier endpoint are removed.</p>\n<p>The sign-in needs Docker (it runs OpenCode in a container) and the agent image built with the OpenCode provider.</p>\n<h3 id=\"claude\">Claude<a class=\"anchor\" href=\"#claude\" aria-label=\"Link to this section\">#</a></h3>\n<p>This is the provider NanoClaw ships with (the Claude Agent SDK), not OpenCode. Its credential is an <strong>Anthropic API key</strong> or a <strong>Claude subscription token</strong>. For a subscription, run <code>claude setup-token</code> in a terminal, sign in as it asks, and paste the token it prints into the panel. <strong>Save</strong> stores it in the gateway as the secret named <em>Anthropic</em> for <code>api.anthropic.com</code>, replacing a previous one.</p>\n<p>Applying Claude sets every agent's provider back to the default (Claude) and, if you enter one, its model; leave the model empty to use the provider's default. The <code>OPENCODE_*</code> settings are left alone, so switching back to an endpoint later is one step.</p>\n<p>As with ChatGPT, the panel cannot check a model name against Anthropic. Use the full name Anthropic gives (for example <code>claude-haiku-4-5-20251001</code>); a short or invented name such as <code>haiku-4.5</code> makes every agent answer with <em>There's an issue with the selected model</em>.</p>\n<h3 id=\"removing-a-credential\">Removing a credential<a class=\"anchor\" href=\"#removing-a-credential\" aria-label=\"Link to this section\">#</a></h3>\n<p>Next to each stored credential there is a <strong>Remove</strong> button (click it twice, then confirm your password). It deletes the secret from the gateway: the ChatGPT login, the OpenAI key (the secret named <em>OpenCode openai</em>) or the Anthropic one. The panel refuses while the agents are using that credential, so switch to another provider first. Removing something that is already gone is not an error. Removing a ChatGPT login here does not sign you out of ChatGPT itself; revoke an API key on the provider's own site as well if you no longer want it to work.</p>\n<h3 id=\"how-a-model-change-works\">How a model change works<a class=\"anchor\" href=\"#how-a-model-change-works\" aria-label=\"Link to this section\">#</a></h3>\n<p>Applying a change (an endpoint, ChatGPT or Claude) does this, in order:</p>\n<ol><li>Checks the endpoint again.</li><li>Writes a <strong>journal</strong> with the previous <code>.env</code> values and every agent's previous provider and model.</li><li>Writes the <code>OPENCODE_*</code> settings to <code>.env</code>: for an endpoint, <code>OPENCODE_PROVIDER</code>, <code>OPENCODE_BASE_URL</code>, <code>OPENCODE_MODEL</code>, <code>OPENCODE_SMALL_MODEL</code> and, when the server reports its context window, <code>OPENCODE_MODEL_CONTEXT_LIMIT</code> and <code>OPENCODE_MODEL_OUTPUT_LIMIT</code> (half the window, at most 4096); for ChatGPT the settings listed in <a href=\"#chatgpt\">ChatGPT</a>; for Claude nothing.</li><li>Sets every agent group's provider and model: <code>opencode</code> and <code>openai/&lt;model&gt;</code>, or the default provider (Claude) with the model you gave.</li><li>Verifies what was written, then restarts every agent.</li><li>Deletes the journal.</li></ol>\n<p>If anything fails before the restarts, or NanoClaw stops in the middle, everything is put back from the journal (automatically at the next start in the second case). A restart that fails after the change was written does not undo it: the affected agents pick the settings up the next time they start. Running turns are interrupted by the restarts.</p>\n<p>Both limits are written together or not at all because OpenCode rejects a context limit without an output limit.</p>\n<h3 id=\"endpoint-checks-and-errors\">Endpoint checks and errors<a class=\"anchor\" href=\"#endpoint-checks-and-errors\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-wrap\"><table><thead><tr><th>Message</th><th>What it means and what to do</th></tr></thead><tbody><tr><td><em>Could not reach the endpoint</em></td><td>Wrong address or port, server down, firewall, or the server listens only on <code>127.0.0.1</code>.</td></tr><tr><td><em>The endpoint does not list that model</em></td><td>The model name differs from what <code>/v1/models</code> returns. Pick one from the suggestions.</td></tr><tr><td><em>The endpoint wants an API key</em></td><td>See <a href=\"#api-keys\">API keys</a>.</td></tr><tr><td><em>Plain HTTP is only accepted for local addresses</em></td><td>Use HTTPS for a public host, or a local address.</td></tr><tr><td><em>That address is not allowed</em></td><td>Link-local, multicast or reserved address.</td></tr><tr><td><em>The name could not be resolved</em></td><td>DNS does not know the host name from the NanoClaw machine.</td></tr><tr><td><em>The TLS certificate could not be verified</em></td><td>Self-signed or expired certificate on an HTTPS endpoint.</td></tr><tr><td><em>The endpoint did not answer like an OpenAI-compatible API</em></td><td>The URL is not the API root (often missing <code>/v1</code>).</td></tr><tr><td><em>The model did not answer a test request</em></td><td>The server lists the model but fails on a completion; check its log.</td></tr><tr><td><em>The change failed and the previous settings were restored</em></td><td>Something broke while applying; nothing changed. Check the NanoClaw log.</td></tr></tbody></table></div>\n<h2 id=\"backups-1\">Backups<a class=\"anchor\" href=\"#backups-1\" aria-label=\"Link to this section\">#</a></h2>\n<h3 id=\"what-a-backup-contains\">What a backup contains<a class=\"anchor\" href=\"#what-a-backup-contains\" aria-label=\"Link to this section\">#</a></h3>\n<p>One encrypted file holding:</p>\n<ul><li>the central database (a consistent snapshot);</li><li>every agent's session data, including each conversation's databases (snapshotted safely);</li><li>agent group folders (memory, files, plugins) and channel stores;</li><li>the <code>.env</code> file and the allowlists in <code>~/.config/nanoclaw</code>;</li><li>a manifest: release, applied migrations, which skills and gateway were installed, counts.</li></ul>\n<p>Left out: sockets and lock files, per-run scratch data, logs, container images (rebuilt after a restore), and the machine's own identity files unless you ask for them (<code>--machine-identity</code>).</p>\n<p><strong>Not included: the credentials in the credential gateway.</strong> After restoring onto a new machine, install the gateway skill and enter the credentials again. The manifest lists which skills and gateway the backup came from.</p>\n<h3 id=\"the-backup-key\">The backup key<a class=\"anchor\" href=\"#the-backup-key\" aria-label=\"Link to this section\">#</a></h3>\n<p>Each backup gets its own random 256-bit key, shown <strong>once</strong>, when the backup is created, as 64 hexadecimal characters in groups of eight. It is not stored anywhere, not even in the panel. Put it in a password manager. Without the key the backup cannot be opened, by anyone.</p>\n<p>The key is needed to verify, restore and inspect a backup, never to list or delete one. In the panel, <strong>Verify</strong> asks for the key; the terminal commands read it from the <code>MANAGER_BACKUP_KEY</code> environment variable, from <code>--key-file &lt;path&gt;</code>, or from a hidden prompt, never from a command-line argument.</p>\n<h3 id=\"consistency-levels\">Consistency levels<a class=\"anchor\" href=\"#consistency-levels\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-wrap\"><table><thead><tr><th>Level</th><th>Meaning</th></tr></thead><tbody><tr><td><code>cold</code></td><td>NanoClaw was stopped. Everything is from the same instant.</td></tr><tr><td><code>quiescent</code></td><td>NanoClaw was running but no agent was working on a message.</td></tr><tr><td><code>best-effort</code></td><td>An agent was working. Each database file is still consistent, but files were not copied at the same instant.</td></tr></tbody></table></div>\n<p>From the panel, <strong>Create backup</strong> first waits (up to 120 seconds by default) for agents that are in the middle of a turn. Agents that are alive but idle do not count. If agents are still busy afterwards the backup is refused, unless you tick <em>Back up even if agents are running</em>, which records <code>best-effort</code>.</p>\n<h3 id=\"retention-and-pruning\">Retention and pruning<a class=\"anchor\" href=\"#retention-and-pruning\" aria-label=\"Link to this section\">#</a></h3>\n<p>Backups accumulate in the backups folder (<code>~/.local/share/nanoclaw-backups/&lt;install&gt;</code> by default, or <code>PANEL_BACKUP_DIR</code> / <code>MANAGER_BACKUP_DIR</code>). The panel can delete single backups; to keep the newest few and one per month:</p>\n<pre><code class=\"language-bash\">pnpm exec tsx scripts/manager-backup.ts prune --keep-last 7 --keep-monthly 6</code></pre>\n<p>Keep copies on <strong>another disk or machine</strong>: a backup next to the data it protects does not protect against losing the disk. A downloaded or copied <code>.mbk</code> file is all you need besides its key.</p>\n<p>Backups from the panel need the panel's reauthentication and a person to save the key. Unattended scheduled backups are not provided: they would require storing the key next to the backups.</p>\n<h3 id=\"restoring-a-backup\">Restoring a backup<a class=\"anchor\" href=\"#restoring-a-backup\" aria-label=\"Link to this section\">#</a></h3>\n<p>Restoring is <strong>terminal-only</strong> and needs NanoClaw <strong>stopped</strong>: it replaces the data the running host is using. Stop the service first (and the agent containers, which keep running on their own), then:</p>\n<pre><code class=\"language-bash\">pnpm exec tsx scripts/manager-backup.ts list\npnpm exec tsx scripts/manager-backup.ts restore &lt;id&gt;</code></pre>\n<p>The command asks for the key, authenticates the whole file before touching anything, prints what it will do, and asks you to type <code>RESTORE</code>. Then it:</p>\n<ol><li>unpacks into a staging area next to the live data;</li><li>swaps <code>data/</code>, <code>groups/</code> and <code>store/</code> by moving their contents (a symlinked or mounted folder keeps its identity), keeping the old state for rollback;</li><li>writes <code>.env</code>, keeping this machine's own <code>ONECLI_*</code>, <code>NANOCLAW_GATEWAY_PROVIDER</code>, <code>PANEL_*</code> and <code>no_proxy</code> settings;</li><li>prepares the database for a clean start: sessions marked stopped, host leases and session claims cleared, derived image tags cleared.</li></ol>\n<p>Facts to know:</p>\n<ul><li>A backup <strong>older</strong> than the installed code is restored, and NanoClaw applies the newer migrations at its next start. A backup <strong>newer</strong> than the installed code is refused: update NanoClaw first.</li><li>This install's own upgrade marker is kept, so the startup check does not trip.</li><li><strong>The gateway selection.</strong> If this machine has no credential gateway selected in <code>.env</code> (an install that did not finish its setup) and the backup's gateway skill is installed here, the restore sets <code>NANOCLAW_GATEWAY_PROVIDER</code> to the backup's value and says so. A machine that already selects a gateway keeps its own choice; if it differs from the backup's, the restore warns.</li><li><strong>Credentials to enter again.</strong> Gateway credentials are not in a backup, but their <strong>names</strong> are (never the values). The restore lists the ones this machine does not have yet, for example <code>OpenCode openai, Anthropic</code>; enter them again in the panel (Model page) or with the gateway's own tools. A backup made while the gateway could not be asked has no list.</li><li>Everything newer than the backup (messages, memory, tasks) is replaced. The rollback copy is the only way back.</li><li>Agent groups whose container image was customised are listed; rebuild them with <code>ncl groups restart --id &lt;group&gt; --rebuild</code>.</li></ul>\n<p>Start NanoClaw and check that it works. Then either keep the result or undo it:</p>\n<pre><code class=\"language-bash\">pnpm exec tsx scripts/manager-backup.ts commit &lt;transaction&gt;     # delete the rollback copy\npnpm exec tsx scripts/manager-backup.ts rollback &lt;transaction&gt;   # put everything back</code></pre>\n<p>The transaction id is printed by <code>restore</code>. If the restore fails part way, it rolls itself back. After <code>commit</code> or <code>rollback</code> only the last transaction's small journal stays in <code>.manager-backup-txn/</code>, so that repeating the command can say what already happened.</p>\n<h3 id=\"rehearsal-restore\">Rehearsal restore<a class=\"anchor\" href=\"#rehearsal-restore\" aria-label=\"Link to this section\">#</a></h3>\n<p><code>restore &lt;id&gt; --rehearsal</code> restores a copy that <strong>cannot act as the original</strong>. Use it to test a backup on a second machine while the first is still running, without two installs answering the same chats. It:</p>\n<ul><li>keeps only a short allowlist of <code>.env</code> settings and drops anything that looks like a token or secret (it prints the names it dropped);</li><li>does not restore channel stores, channel login files or the machine's identity;</li><li>marks pending tasks as paused and closes pending chat messages.</li></ul>\n<p>Conversation history, memory and the agents' files are kept. To go live afterwards, do a normal restore (or reinstall the channels' credentials yourself).</p>\n<h3 id=\"moving-to-another-machine\">Moving to another machine<a class=\"anchor\" href=\"#moving-to-another-machine\" aria-label=\"Link to this section\">#</a></h3>\n<ol><li>On the old machine: create a backup (cold, with NanoClaw stopped, if you can) and save the key.</li><li>On the new machine: install NanoClaw, the gateway, the provider and both manager skills, plus the channel skills the backup used (the restore warns about missing ones). Re-enter the gateway credentials.</li><li>Copy the <code>.mbk</code> file into the new backups folder (or pass its path to <code>restore</code>).</li><li>Run a <a href=\"#rehearsal-restore\">rehearsal restore</a> first, check the agents, then restore for real with the old machine stopped, so that two installs never talk to the same accounts.</li></ol>\n<h2 id=\"terminal-only-tasks\">Terminal-only tasks<a class=\"anchor\" href=\"#terminal-only-tasks\" aria-label=\"Link to this section\">#</a></h2>\n<p>These are deliberately not in the panel. Each is a short recipe; all commands run in the NanoClaw install folder as the NanoClaw user.</p>\n<div class=\"table-wrap\"><table><thead><tr><th>Task</th><th>Where</th></tr></thead><tbody><tr><td>Create the administrator, or get a new setup code</td><td><a href=\"#create-the-administrator\">Create the administrator</a></td></tr><tr><td>Forgot the password, locked out, sign everyone out</td><td><a href=\"#forgotten-password\">Forgotten password</a></td></tr><tr><td>Store or change a model provider's API key (also possible in the panel)</td><td><a href=\"#api-keys\">API keys</a></td></tr><tr><td>Restore a backup, roll back a restore</td><td><a href=\"#restoring-a-backup\">Restoring a backup</a></td></tr><tr><td>Test a backup on another machine</td><td><a href=\"#rehearsal-restore\">Rehearsal restore</a></td></tr><tr><td>Prune old backups</td><td><a href=\"#retention-and-pruning\">Retention and pruning</a></td></tr><tr><td>Open the panel to the network or enable HTTPS</td><td><a href=\"#https-and-network-access\">HTTPS and network access</a></td></tr><tr><td>Add channels and agents</td><td><a href=\"#channels-and-agents\">Channels and agents</a></td></tr><tr><td>Update NanoClaw</td><td><a href=\"#updating-nanoclaw\">Updating NanoClaw</a></td></tr><tr><td>Rebuild an agent's image</td><td><a href=\"#rebuilding-agent-images\">Rebuilding agent images</a></td></tr><tr><td>Uninstall</td><td><a href=\"#removing-the-skills\">Removing the skills</a></td></tr></tbody></table></div>\n<h3 id=\"forgotten-password\">Forgotten password<a class=\"anchor\" href=\"#forgotten-password\" aria-label=\"Link to this section\">#</a></h3>\n<p>From a terminal on the machine:</p>\n<pre><code class=\"language-bash\">pnpm exec tsx scripts/manager-panel.ts reset-password   # asks twice, hidden; signs everyone out\npnpm exec tsx scripts/manager-panel.ts unlock           # clear the lock after too many wrong passwords\npnpm exec tsx scripts/manager-panel.ts revoke-sessions  # sign every browser out\npnpm exec tsx scripts/manager-panel.ts status           # address, administrator set up?, failed logins</code></pre>\n<p>Whoever can run these has the same access as the NanoClaw user, so this is the recovery path and also the reason to keep the machine itself protected.</p>\n<h3 id=\"channels-and-agents\">Channels and agents<a class=\"anchor\" href=\"#channels-and-agents\" aria-label=\"Link to this section\">#</a></h3>\n<p>The panel shows the channels that are installed and the agents that exist; it does not create them. Use upstream's tools: the setup wizard, <code>/manage-channels</code>, <code>/add-telegram</code>, <code>/add-signal</code> and the other <code>/add-*</code> skills in Claude Code, <code>scripts/init-first-agent.ts</code>, and the <code>ncl</code> command-line tool (<code>bin/ncl groups ...</code>). Follow upstream's documentation for those. After installing a channel skill, restart NanoClaw; the new channel shows on the panel's Overview.</p>\n<h3 id=\"updating-nanoclaw\">Updating NanoClaw<a class=\"anchor\" href=\"#updating-nanoclaw\" aria-label=\"Link to this section\">#</a></h3>\n<p>Use upstream's flow from Claude Code, in the install folder:</p>\n<pre><code>/update-nanoclaw</code></pre>\n<p>It works in a staging copy, takes a snapshot, runs the migrations, checks health and rolls back by itself on failure. Before updating, create a backup from the panel or the terminal.</p>\n<p>Upstream refreshes only the channel and provider skills it knows. The manager skills are local code: after an update, fetch the latest version of this repository, copy the two skill folders over the installed ones and run <code>/add-manager-backup</code> and <code>/add-manager-panel</code> again, then rebuild and restart. The nightly job of this repository applies the skills to upstream's newest code and reports when an upstream change breaks one, so check the repository before updating if you are unsure.</p>\n<h3 id=\"rebuilding-agent-images\">Rebuilding agent images<a class=\"anchor\" href=\"#rebuilding-agent-images\" aria-label=\"Link to this section\">#</a></h3>\n<p>Agent groups can have a customised container image (extra packages). Images are not part of a backup. After a restore, or when you change a group's packages:</p>\n<pre><code class=\"language-bash\">bin/ncl groups restart --id &lt;group-id&gt; --rebuild</code></pre>\n<h3 id=\"removing-the-skills\">Removing the skills<a class=\"anchor\" href=\"#removing-the-skills\" aria-label=\"Link to this section\">#</a></h3>\n<p>Each skill has a <code>REMOVE.md</code> that lists exactly what to undo: delete the copied files, delete the one import line from <code>src/modules/index.ts</code>, rebuild. Remove the panel before the backup skill (the panel uses the backup library). Your backups and the <code>data/manager-panel/</code> folder (password hash, audit log) are yours to delete.</p>\n<h2 id=\"security-model\">Security model<a class=\"anchor\" href=\"#security-model\" aria-label=\"Link to this section\">#</a></h2>\n<ul><li>One administrator. The password is hashed with scrypt (memory-hard) and never stored or logged.</li><li>Wrong passwords: five free, then a growing lock that survives restarts.</li><li>Sessions are server-side, in memory (a restart signs everyone out), with an unguessable 256-bit token in an <code>HttpOnly</code>, <code>SameSite=Strict</code> cookie.</li><li>Every request must carry a local <code>Host</code>; cross-site requests are refused; every state change needs the CSRF token <strong>and</strong> an <code>Origin</code> equal to the panel's own.</li><li>Sensitive actions need the password again within the last five minutes.</li><li>Connections from public internet addresses are refused unless <code>PANEL_ALLOW_PUBLIC=true</code>.</li><li>Responses are built field by field: no credentials, no filesystem paths, no log lines, no internal ids (agents are shown under keyed hashes). Error responses carry a code and a request id only.</li><li>State changes are audited (time, action, status, request id; never bodies) in <code>data/manager-panel/audit.jsonl</code>.</li><li>Backups are encrypted with AES-256-GCM in authenticated chunks; a wrong key, a changed bit, a truncated or reordered file is rejected. The key never touches the disk of the machine.</li><li>The panel runs with the NanoClaw user's privileges.</li></ul>\n<h2 id=\"troubleshooting\">Troubleshooting<a class=\"anchor\" href=\"#troubleshooting\" aria-label=\"Link to this section\">#</a></h2>\n<div class=\"table-wrap\"><table><thead><tr><th>Symptom</th><th>Cause and fix</th></tr></thead><tbody><tr><td>NanoClaw prints <em>upgrade tripwire</em> and stops</td><td>The tree changed outside setup. See <a href=\"#after-installing-the-upgrade-check\">After installing: the upgrade check</a>.</td></tr><tr><td>No panel, log says <em>did not start</em></td><td>The log line names the cause: port in use (<code>PANEL_PORT</code>), unreadable certificate files, invalid setting. NanoClaw itself keeps running.</td></tr><tr><td>Panel opens but says <em>host_not_allowed</em> (421)</td><td>The address uses a name that is not local. Add it to <code>PANEL_ALLOWED_HOSTS</code>.</td></tr><tr><td><em>network_not_allowed</em> (403)</td><td>The request came from a public internet address. Intended; see <a href=\"#security-model\">Security model</a>.</td></tr><tr><td><em>origin_mismatch</em></td><td>Behind a proxy or with a different name than expected: set <code>PANEL_PUBLIC_ORIGIN</code>.</td></tr><tr><td>Cannot sign in, <em>login_throttled</em></td><td>Too many wrong passwords. Wait, or run <code>scripts/manager-panel.ts unlock</code>.</td></tr><tr><td><em>Create backup</em> says agents are still running</td><td>An agent is working. Retry later, or tick <em>Back up even if agents are running</em>.</td></tr><tr><td>Agents fail with <em>Missing key limit.output</em></td><td>An old panel version wrote a context limit without an output limit; apply the model once more from the current panel.</td></tr><tr><td>Agent answers nothing, container log says no <code>&lt;message&gt;</code> blocks</td><td>The model does not follow NanoClaw's reply format. Use a model that follows instructions.</td></tr><tr><td>After a model change an agent still uses the old one</td><td>Its restart failed (look in the host log for <em>Failed to stop session</em>). Run <em>Restart</em> again, or <code>docker rm -f</code> the stuck container.</td></tr><tr><td><em>Provider credentials need the OpenCode and OneCLI skills installed</em></td><td>The helper that stores keys is built on <code>add-opencode</code> and <code>add-onecli</code>. Install them, then apply the panel skill again.</td></tr><tr><td><em>The credential gateway is not reachable</em></td><td>OneCLI is not running. Check it (<code>docker ps</code>) and the <code>ONECLI_URL</code> in <code>.env</code>.</td></tr><tr><td>The ChatGPT sign-in shows no page and code</td><td>Docker is not available to the NanoClaw user, or the agent image is missing. Build it (<code>./container/build.sh build</code>) and retry.</td></tr><tr><td>Apply says <em>credential_missing</em></td><td>The credential for that provider is not stored yet. Save the key or sign in first.</td></tr><tr><td>Restore refuses: <em>host_running</em></td><td>NanoClaw is still running. Stop it first.</td></tr><tr><td>Restore refuses: <em>backup_newer</em></td><td>The backup was made by newer code. Update NanoClaw, then restore.</td></tr><tr><td>Restore warns: <em>not installed on this host</em></td><td>The backup used channels or a gateway this install lacks. Install those skills before starting.</td></tr><tr><td>Verify says <em>wrong key, or the backup is damaged</em></td><td>Wrong key or a damaged file. The two cannot be told apart by design.</td></tr><tr><td>Model check: <em>Could not reach the endpoint</em> from a server on the same machine</td><td>Use the Docker bridge address, and make the server listen on it. See <a href=\"#connecting-an-endpoint\">Connecting an endpoint</a>.</td></tr></tbody></table></div>\n<p>When asking for help, include the NanoClaw log lines around the problem and the request id shown in the error (never the key, the password or the contents of <code>.env</code>).</p>\n<h2 id=\"reference\">Reference<a class=\"anchor\" href=\"#reference\" aria-label=\"Link to this section\">#</a></h2>\n<h3 id=\"settings\">Settings<a class=\"anchor\" href=\"#settings\" aria-label=\"Link to this section\">#</a></h3>\n<p>All optional, in the install's <code>.env</code> (or the environment).</p>\n<div class=\"table-wrap\"><table><thead><tr><th>Setting</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td><code>PANEL_ENABLED</code></td><td><code>true</code></td><td><code>false</code> turns the panel off.</td></tr><tr><td><code>PANEL_BIND</code></td><td><code>127.0.0.1</code></td><td>Address to listen on. <code>0.0.0.0</code> for all interfaces.</td></tr><tr><td><code>PANEL_PORT</code></td><td><code>3200</code></td><td>Port.</td></tr><tr><td><code>PANEL_PUBLIC_ORIGIN</code></td><td>unset</td><td>The exact origin browsers use when behind a proxy, such as <code>https://panel.example.org</code>.</td></tr><tr><td><code>PANEL_ALLOWED_HOSTS</code></td><td>unset</td><td>Comma-separated extra host names accepted.</td></tr><tr><td><code>PANEL_TLS_CERT</code>, <code>PANEL_TLS_KEY</code></td><td>unset</td><td>PEM files to serve HTTPS directly. Set both or neither.</td></tr><tr><td><code>PANEL_ALLOW_PUBLIC</code></td><td><code>false</code></td><td><code>true</code> accepts connections from public internet addresses. Not recommended.</td></tr><tr><td><code>PANEL_BACKUP_DIR</code></td><td><code>~/.local/share/nanoclaw-backups/&lt;install&gt;</code></td><td>Where the panel keeps backups.</td></tr><tr><td><code>PANEL_BACKUP_WAIT_SECONDS</code></td><td><code>120</code></td><td>How long a backup waits for busy agents.</td></tr><tr><td><code>MANAGER_BACKUP_DIR</code></td><td>same as above</td><td>Backups folder for the terminal tool.</td></tr><tr><td><code>MANAGER_BACKUP_KEY</code></td><td>unset</td><td>The key for the terminal tool (prefer <code>--key-file</code> or the prompt).</td></tr></tbody></table></div>\n<h3 id=\"terminal-commands\">Terminal commands<a class=\"anchor\" href=\"#terminal-commands\" aria-label=\"Link to this section\">#</a></h3>\n<pre><code class=\"language-text\">scripts/manager-backup.ts create [--machine-identity]\nscripts/manager-backup.ts list\nscripts/manager-backup.ts verify &lt;id|file&gt;\nscripts/manager-backup.ts restore &lt;id|file&gt; [--rehearsal] [--machine-identity] [--yes]\nscripts/manager-backup.ts commit &lt;transaction&gt;\nscripts/manager-backup.ts rollback &lt;transaction&gt;\nscripts/manager-backup.ts prune [--keep-last N] [--keep-monthly N]\n        (all accept --dir &lt;folder&gt; and --key-file &lt;path&gt;)\n\nscripts/manager-panel.ts setup-code | reset-password | revoke-sessions | unlock | status</code></pre>\n<p>Run them as <code>pnpm exec tsx scripts/&lt;name&gt;.ts ...</code>.</p>\n<h3 id=\"files-and-folders\">Files and folders<a class=\"anchor\" href=\"#files-and-folders\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-wrap\"><table><thead><tr><th>Path</th><th>What</th></tr></thead><tbody><tr><td><code>data/manager-panel/</code></td><td>Panel state, private (mode 0700): password hash, login lock, audit log, identifier key, model-change journal. Included in backups.</td></tr><tr><td><code>~/.local/share/nanoclaw-backups/&lt;install&gt;/</code></td><td>Backups (<code>&lt;id&gt;.mbk</code>) and their small description files (<code>&lt;id&gt;.meta.json</code>).</td></tr><tr><td><code>.manager-backup-txn/</code> inside <code>data/</code>, <code>groups/</code>, <code>store/</code></td><td>Rollback copies during a restore; removed by <code>commit</code> or <code>rollback</code>.</td></tr><tr><td><code>src/modules/manager-backup/</code>, <code>src/modules/manager-panel/</code></td><td>The skills' code.</td></tr></tbody></table></div>\n<h3 id=\"http-api\">HTTP API<a class=\"anchor\" href=\"#http-api\" aria-label=\"Link to this section\">#</a></h3>\n<p>For the curious or for scripting. Everything is under <code>/api/v1</code>, JSON, <code>Cache-Control: no-store</code>. State-changing calls need the cookie, the <code>X-CSRF-Token</code> header and an <code>Origin</code> equal to the panel's.</p>\n<div class=\"table-wrap\"><table><thead><tr><th>Method and path</th><th>Needs password again</th><th>What</th></tr></thead><tbody><tr><td><code>GET /health</code></td><td>no</td><td><code>{&quot;status&quot;:&quot;ok&quot;}</code>, no session needed</td></tr><tr><td><code>GET /setup</code>, <code>POST /setup</code></td><td>no</td><td>first-run status; create the administrator</td></tr><tr><td><code>POST /session</code>, <code>GET /session</code>, <code>DELETE /session</code></td><td>no</td><td>sign in, read session, sign out</td></tr><tr><td><code>POST /session/reauth</code></td><td>no</td><td>type the password again</td></tr><tr><td><code>GET /overview</code>, <code>GET /agents</code>, <code>GET /channels</code></td><td>no</td><td>read</td></tr><tr><td><code>POST /agents/{id}/restart</code></td><td>no</td><td>restart an agent</td></tr><tr><td><code>GET /model</code></td><td>no</td><td>current model settings</td></tr><tr><td><code>POST /model/preflight</code></td><td>no</td><td>check a provider choice (<code>kind</code>: <code>compatible</code>, <code>chatgpt</code> or <code>claude</code>)</td></tr><tr><td><code>POST /model/apply</code></td><td>yes</td><td>apply it to all agents</td></tr><tr><td><code>GET /credentials</code></td><td>no</td><td>which provider credentials are stored (booleans)</td></tr><tr><td><code>POST /credentials/claude</code>, <code>POST /credentials/openai-key</code></td><td>yes</td><td>store a key or token; nothing is returned</td></tr><tr><td><code>DELETE /credentials/claude</code>, <code>/openai-key</code>, <code>/chatgpt-login</code></td><td>yes</td><td>remove a stored credential; refused with 409 while in use</td></tr><tr><td><code>POST</code>, <code>GET</code>, <code>DELETE /credentials/chatgpt/login</code></td><td>start: yes</td><td>ChatGPT device sign-in: start, poll for page and code, cancel</td></tr><tr><td><code>GET /backups</code></td><td>no</td><td>list</td></tr><tr><td><code>POST /backups</code></td><td>yes</td><td>create; the response holds the key, once</td></tr><tr><td><code>POST /backups/{id}/verify</code></td><td>no</td><td>verify with a key</td></tr><tr><td><code>GET /backups/{id}/download</code></td><td>yes</td><td>the encrypted file</td></tr><tr><td><code>DELETE /backups/{id}</code></td><td>yes</td><td>delete</td></tr></tbody></table></div>\n<h2 id=\"known-limits\">Known limits<a class=\"anchor\" href=\"#known-limits\" aria-label=\"Link to this section\">#</a></h2>\n<ul><li>One provider for all agents; a different provider per agent is not offered.</li><li>The panel cannot check a ChatGPT or Claude model name, because the keys live in the gateway.</li><li>The ChatGPT sign-in and the Claude credential were tested against the real gateway and, for the sign-in, against OpenAI's real pairing page, but not completed with a real account.</li><li>Restoring and updating are terminal-only.</li><li>Credentials in the gateway are not part of backups.</li><li>The panel starts and stops with NanoClaw; it cannot start NanoClaw.</li><li>A restart requested from the panel is reported as done even if a stuck container could not be removed; check the log if an agent keeps its old behaviour.</li><li>Tested on a single Debian 13 host with one agent and a mock model server. Channels, several machines and long-running installs have not been exercised.</li><li>The guide's nginx example, <code>/update-nanoclaw</code> followed by re-applying the skills, and applying the skills with the <code>/add-manager-*</code> commands in Claude Code have not been tried end to end.</li></ul>\n</main>\n</div>\n</body>\n</html>\n"; // privacy-scan: allow -- generated; docs/guide.md carries its own markers
